node -e "
const XLSX = require('xlsx');

// Create a new workbook
const wb = XLSX.utils.book_new();

// Create sheet data with headers and the note
const data = [
  ['Route', 'Date', 'Status', 'Notes'],
  ['LAX to SFO', '2026-09-05', 'No flights found', 'No flight information was found for LAX to SFO on 2026-09-05.']
];

const ws = XLSX.utils.aoa_to_sheet(data);

// Set column widths for readability
ws['!cols'] = [
  { wch: 14 },
  { wch: 12 },
  { wch: 18 },
  { wch: 60 }
];

XLSX.utils.book_append_sheet(wb, ws, 'Travel Expenses');

XLSX.writeFile(wb, 'skills/OfficeBench/testbed/data/travel_expenses.xlsx');
console.log('File created successfully.');
"

